INSERT INTO _fleet_sync_transfer_phase_history(attempt,position,phase_kind,final_epoch,final_sequence,entered_at,created_at,updated_at) SELECT ?1,j.key,json_extract(j.value,'$.phase.phase'),NULLIF(j.value -> '$.phase.finalPosition.epoch','null'),NULLIF(j.value -> '$.phase.finalPosition.sequence','null'),json_extract(j.value,'$.enteredAt'),CAST(?3 AS INTEGER),CAST(?4 AS INTEGER) FROM json_each(?2) AS j WHERE true ON CONFLICT(attempt,position) DO NOTHING
